insert into store.products (slug, name, description, features, featured) values ('zener-diodes-pack-of-140', 'Zener Diodes (pack of 140)', 'Bypass normally-closed alarm systems that use end-of-line resistors: measure the voltage, then jumper the wires with a zener diode of that voltage in series. Includes 10 each of 3.3V, 3.9V, 4.7V, 5.1V, 6.2V, 6.8V, 8.2V, 10V, 12V, 15V, 16V, 18V, 20V and 24V.', '{}'::text[], false);
