insert into store.products (slug, name, description, features, featured) values ('bypass-measurement-wallet-card', 'Bypass & Measurement Wallet Card', 'Designed in house by the Village, this stainless wallet card does 27 different things.', array['Large Latch Slip — insert behind a latch to retract it','Small Latch Slip — same as above','Latch Shove — retract latches with the bevel facing you','General Key Gauge — slide a key up as far as it goes on each cut; the number is the cut depth in thousandths of an inch','Schlage Key Gauge — slide a Schlage key down as far as it goes; the step it stops at is the cut depth','Medeco Key Gauge — general key gauge markings for Medeco depths','Kwikset Key Gauge — general key gauge markings for Kwikset depths','Pin Gauge — slide a pin (or tiny key) as high as it goes to read pin lengths in thou','Wire Gauge — slide a wire as high as it goes to read the AWG measure','Tubular Key Gauge — hold a tubular cut up to each of the eight steps to see which it matches','Medeco Biaxial Fore / Aft Gauge — place the shoulder at the “m” marking and match the cuts to the tick marks','Grid for Key Photographing — place a key on the grid and photograph it to allow perspective correction later','Keyway Photographing Hole / Lanyard Hole — photograph the keyway head on while keeping the camera in focus','Level / Plumb Bob — dangle the card from the bottom left hole; the c-clamp point at top right points vertical from it','Spanner Screwdriver — 6mm spanner screws, common on HID wall readers','⅜" Wrench — a very low quality wrench','¼" Wrench — a very low quality wrench, but smaller','Ruler — a short ruler; the wrench edge corresponds to 0','Compass — ¼" spaced holes that can be spun to make circles of ¼" increment size','Protractor — markings show the angle up from the card bottom','Medeco Pin Angle Reference — looking from above, tell left, centre and right pins apart relative to their tab in classic (90°) and biaxial (180°)','Tension Wrench — works in a pinch','Tubular Tension Wrench — insert the rectangle into the cutout and the triangle into the edge of the card','Terminal Block Jumper — jumper out enterphones and door relays to gain access','C-Clamp Remover — press into the c-clamp on the rear of a lock','Rim and Mortise Cylinder Drilling Jig — insert a key into the keyway hole; the round hole is now over the rim retaining screw. Centre punch the location, flip the card to get the other side, then drill. There is also a marking for where a mortise retaining screw will be','RFID Blocker — keep this card in your wallet and it blocks RFID reads except when touching the wallet (similar performance to other RFID wallet blockers that only do that)']::text[], false);
