insert into store.collections (slug, title, tag, blurb, description, position) values ('lishi', 'Lishi Tools', '$100 each', 'Lishi tools are revolutionary lockpicks. If you are unfamiliar with them, we encourage you to look up some of the excellent content creators like LockPickingLawyer and LockNoob have put out.', 'A Lishi simulates a key: use the numbered grid to position the pick at the exact position of each pin, then push down until you feel, hear or see the “click” of the pin being set. Once the lock is picked, the plug is turned and the key pins are trapped within it. The pick can now decode the lock — read the depths off the grid and you can make a functioning key for it.
