insert into store.collection_groups (collection_id, title, tag, lede, position) select id, 'Enterphone Keys', '', 'Building intercoms — “enterphones” — are used to buzz up and access a building, but for most models all the logic resides in the unit itself, and they are keyed alike. Use the key to open the unit, then jumper out the leads or wave a magnet over the relay to unlock the door. Try it in the Village.', 1 from store.collections where slug = 'specialty-keys';
