insert into store.collection_groups (collection_id, title, tag, lede, position) select id, 'Construction Keys', '', 'Construction locks are used while a building is being built, and are supposed to be swapped out for different locks once construction is complete. This occasionally doesn''t happen. If you ever see an IC core (figure 8 shape) painted black or orange (Schlage) or green (BEST), it will be keyed to one of these. We cut our Schlage construction keys on black anodised blanks so the key matches the lock.', 2 from store.collections where slug = 'specialty-keys';
