insert into store.collection_items (group_id, product_id, position) select g.id, p.id, 4 from store.collection_groups g join store.collections c on c.id = g.collection_id, store.products p where c.slug = 'specialty-keys' and g.position = 2 and p.slug = 'best-green-construction-key';
insert into store.collection_groups (collection_id, title, tag, lede, position) select id, 'Ford Fleet Keys', '', 'When a large company or department orders a fleet of vehicles using the same key, Ford often keys it to one of seven keys — with 1284X being the most common. Many fleet vehicles across the continent (utility trucks, police cruisers, taxicabs) are keyed to one of these. We carry the 7 most common: 0135X, 0151X, 0576X, 1111X, 1284X, 1294X and 1435X.', 3 from store.collections where slug = 'specialty-keys';
